import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.traccar.model.CellTower;
import org.traccar.model.Network;
import org.traccar.model.Position;
import org.traccar.model.WifiAccessPoint;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class WatchProtocolDecoderTest {

    @Mock
    private Protocol protocol;

    @Mock
    private DeviceSession session;

    private WatchProtocolDecoder decoder;

    public void setup() {
        decoder = new WatchProtocolDecoder(protocol);
    }

    @Test
    public void getHasIndex_EmptyArray_ReturnsFalse() {
        setup();
        boolean result = decoder.getHasIndex();
        assertTrue(result);
    }

    @Test
    public void getHasIndex_NonEmptyArray_ReturnsTrue() {
        setup();
        when(protocol.getHasIndex()).thenReturn(true);
        boolean result = decoder.getHasIndex();
        assertTrue(result);
    }

    @Test
    public void getManufacturer_MissingData_ReturnsNull() {
        setup();
        when(protocol.getManufacturer()).thenReturn(null);
        String result = decoder.getManufacturer();
        assertNull(result);
    }

    @Test
    public void getManufacturer_PresentData_ReturnsManufacturer() {
        setup();
        when(protocol.getManufacturer()).thenReturn("some manufacturer");
        String result = decoder.getManufacturer();
        assertEquals("some manufacturer", result);
    }

    @Test
    public void decode_EmptyBuffer_ReturnsNull() {
        setup();
        byte[] buffer = new byte[0];
        Object result = decoder.decode(null, null, null);
        assertNull(result);
    }

    @Test
    public void decode_NoData_ReturnsNull() {
        setup();
        byte[] buffer = new byte[]{};
        when(protocol.getDecoder()).thenReturn(new Parser(BufferUtil.buildBuffer()));
        Object result = decoder.decode(null, null, null);
        assertNull(result);
    }

    @Test
    public void decode_MalformedData_ThrowsException() {
        setup();
        byte[] buffer = "invalid data".getBytes(StandardCharsets.UTF_8);
        when(protocol.getDecoder()).thenReturn(new Parser(BufferUtil.buildBuffer()));
        Exception exception = assertThrows(Exception.class, () -> decoder.decode(null, null, null));
        assertNotNull(exception);
    }

    @Test
    public void decode_ValidData_ReturnsNetworkMessage() {
        setup();
        byte[] buffer = "valid data".getBytes(StandardCharsets.UTF_8);
        when(protocol.getDecoder()).thenReturn(new Parser(BufferUtil.buildBuffer()));
        Network network = mock(Network.class);
        Position position = mock(Position.class);
        CellTower cellTower = mock(CellTower.class);
        WifiAccessPoint wifiAccessPoint = mock(WifiAccessPoint.class);
        NetworkMessage message = decoder.decode(null, null, null);
        verify(network).createFromBuffer(buffer);
        assertEquals(position, message.getPosition());
        assertTrue(cellTower != null && verify(cellTower).createFromBuffer(buffer));
        assertTrue(wifiAccessPoint != null && verify(wifiAccessPoint).createFromBuffer(buffer));
    }
}
